package com.aabhix.camera.validation;
import android.graphics.*;import com.aabhix.camera.*;import com.aabhix.camera.domain.*;import org.json.*;
final class PhotoRasterValidation {
    static JSONObject run()throws Exception{Bitmap source=Bitmap.createBitmap(96,128,Bitmap.Config.ARGB_8888);int[] pixels=new int[96*128];java.util.Random random=new java.util.Random(9);for(int i=0;i<pixels.length;i++)pixels[i]=0xff000000|random.nextInt(0x1000000);source.setPixels(pixels,0,96,0,0,96,128);int cases=0,max=0;try{for(int orientation=1;orientation<=8;orientation++)for(float aspect:new float[]{0,1,4f/3,16f/9})for(Style style:new Style[]{Style.identity(),Style.builtins().get(12),Style.builtins().get(25)}){Bitmap normalized=Bitmap.createBitmap(source,0,0,96,128,PhotoRasterizer.orientation(orientation),true);Bitmap expected=normalized.copy(Bitmap.Config.ARGB_8888,true);if(normalized!=source)normalized.recycle();if(aspect>0){int[] rectangle=FrameGeometry.crop(expected.getWidth(),expected.getHeight(),aspect);Bitmap cut=Bitmap.createBitmap(expected,rectangle[0],rectangle[1],rectangle[2],rectangle[3]);if(cut!=expected){expected.recycle();expected=cut.copy(Bitmap.Config.ARGB_8888,true);cut.recycle();}}PhotoColorProcessor.apply(expected,style,.7f);Bitmap actual=PhotoRasterizer.render(source,orientation,aspect,style,.7f);try{if(expected.getWidth()!=actual.getWidth()||expected.getHeight()!=actual.getHeight())throw new IllegalStateException("Raster geometry differs");for(int y=0;y<actual.getHeight();y++)for(int x=0;x<actual.getWidth();x++){int a=actual.getPixel(x,y),b=expected.getPixel(x,y);for(int shift:new int[]{0,8,16})max=Math.max(max,Math.abs((a>>shift&255)-(b>>shift&255)));}}finally{actual.recycle();expected.recycle();}cases++;}}finally{source.recycle();}if(max>2)throw new IllegalStateException("Fused geometry/color mismatch "+max);return new JSONObject().put("cases",cases).put("max_channel_error",max).put("passed",true);}
}
